from pathlib import Path
from collections import Counter
import json

ROOT=Path('D:/00物联网平台/research')
items=[]
def add(n,domain,title,typ,description,persona,value,p,acceptance,deps,owner,surface,condition='所有首销网关型号',notes=''):
 items.append({'id':f'OH-{n:03d}','domain':domain,'title':title,'type':typ,'description':description,'persona':persona,'value':value,'priority':p,'phase':{'P0':'首期','P1':'规模化','P2':'订单驱动'}[p],'acceptance':acceptance,'dependencies':[f'OH-{d:03d}' for d in deps],'owner_role':owner,'status':'待确认','source_basis':'设计建议','surface':surface,'condition':condition,'notes':notes})

add(1,'产品边界','确认网关产品与开发者服务边界','业务','平台服务自有网关的交付、管理和客户开发应用，明确首销SKU、固件与接口承诺。客户可通过网关采集其第三方BLE终端数据，业务解释和应用开发由客户负责；不接入第三方网关。','产品与解决方案负责人','让平台投入直接服务网关销售','P0','形成网关SKU、扫描与连接能力、接口和应用责任表；演示客户终端原始数据可取得但不被宣称已完成业务解析。',[],'产品','平台基础')
add(2,'服务政策','定义硬件随附平台服务权益','业务','分别约定硬件所有权、网关管理云服务、软件维护和保修期限。明确基础功能、调试数据窗口、支持与通知范围，不默认永久免费云服务。','销售与客户管理员','避免硬件一次收费带来无限服务责任','P0','每个首销SKU有权益说明；样本可同时显示不同保修与云服务期；未约定到期行为不能自动停服。',[1],'产品与商务','平台基础')
add(3,'客户组织','建立客户项目和设备组','功能','客户拥有独立网关资源和管理空间，按项目、站点或设备组分类；平台不承载客户应用的业务对象和业务流程。','客户管理员','管理购入的网关并分配开发权限','P0','两个客户各自创建项目和网关组，互不可读写；同客户内筛选结果与设备归属一致。',[1],'平台后端','客户控制台')
add(4,'客户组织','提供成员和基础角色','功能','提供客户管理员、开发者、操作员和只读角色，按项目或设备组授予网关查看、配置、调试和导出权限，支持邀请及禁用。','客户管理员','避免共享账号和误操作','P0','各角色完成允许动作且越权拒绝；禁用成员后其会话按批准窗口失效，个人账号不充当生产程序密钥。',[3],'平台后端','客户控制台')
add(5,'平台安全','保护内部高权限登录','技术','内部设备运营、支持和固件发布使用独立实名账号及MFA，限制登录重试、会话时长和批量高风险操作权限。','内部管理员','降低后台账户被接管的影响','P0','内部高权限用户未完成MFA不能发布固件或访问支持后台；失败重试触发限制并留下审计。',[4],'安全与平台后端','内部运营售后台')
add(6,'设备身份','建立SN和独立认证凭据','技术','每台自有网关记录不可变设备ID、SN、型号、硬件版本和证书指纹；SN不作为唯一认证秘密。凭据可轮换、吊销且不在日志和普通导出中明文出现。','设备运营与固件人员','使硬件可信接入并可追溯','P0','重复SN拒绝建档；仅伪造SN但无凭据的设备不能接入；吊销一台只影响该台，轮换过程和秘密保护可验证。',[1],'固件与平台后端','平台基础')
add(7,'出厂交付','导入生产批次和产测记录','功能','先用CSV或已有工具导出文件关联SN、批次、型号、产测结论与时间；不建设完整MES。未通过产测的设备进入异常状态，不能按正常流程出货激活。','工厂与质量人员','支持出货追溯和售后判定','P0','导入通过、失败、重复SN及缺字段样本并逐行报错；可由SN追到产测结果，失败设备的激活受控。',[6],'质量与设备运营','出厂与交付工具')
add(8,'设备激活','认领激活并绑定客户','功能','客户使用二维码或SN加一次性认领凭据激活网关；内部可按订单代绑定。网关只能同时归属一个客户，认领与出厂身份校验分开。','客户管理员与交付人员','缩短开箱上线并防止误认领','P0','重复认领不产生新设备，已使用认领码不可被其他客户抢占；异常产测或失窃设备不能正常激活。',[3,6,7],'平台后端','客户控制台')
add(9,'设备激活','处理重置转移和退役','功能','恢复出厂设置不自动改变客户归属；客户转移、返修或退役时经授权撤销旧管理访问，清除或替换旧客户数据端点及凭据，保留历史审计归属。','客户管理员与售后','避免二次交付泄漏客户凭据和数据','P0','重置后不能被未授权客户直接认领；转移后旧账号不能控制网关，旧端点秘密不随设备交给新客户；操作原因可追溯。',[4,8],'售后与平台后端','内部运营售后台')
add(10,'安装交付','提供本地配网和网络恢复','功能','针对首销网关提供至少一种本地配网入口，配置网络、时间及管理服务地址；管理云不可达时仍能执行必要本地网络修复。','客户开发者与安装人员','减少首次安装和网络变更售后','P0','分别验证错误WiFi密码、无互联网、管理云不可达及重启；能区分局域网连通和管理云连接成功，按指南完成恢复。',[6,8],'固件与客户端','出厂与交付工具')
add(11,'客户数据通道','直连客户MQTT或HTTPS服务','技术','控制面连接我方管理服务，BLE数据面按客户配置直达其MQTT或HTTPS端点；首期按首销SKU实现至少一种经验证协议，不默认双发。支持端点、主题或路径、证书及受控凭据配置。','客户开发者','客户直接开发应用并减少我方云数据成本','P0','参考客户端能从客户测试端点收到网关数据；错误地址、鉴权失败、证书错误有明确结果；普通运行不向我方云复制客户BLE载荷。',[10,12,13,17,30],'固件与平台后端','客户控制台',notes='直连的数据可靠性边界取决于客户Broker或HTTP接收服务；客户端点凭据不得通过普通日志或查询API回显。')
add(12,'型号能力','公布型号和固件能力契约','技术','按自有网关SKU记录扫描、PHY、广告扩展、过滤、连接读写、并发、缓存、网络、上行协议及升级恢复能力。可接客户BLE终端不等于支持其私有业务协议。','客户开发者与销售','使售卖承诺可验证','P0','每个首销SKU有能力表与固件依赖；控制台及API拒绝不支持的操作，不以蓝牙版本标签代替实测能力。',[1,6],'产品与固件','平台基础')
add(13,'数据契约','提供版本化原始数据封装','技术','对广播和适用的连接数据提供稳定信封，含网关ID、报文类型、地址及类型、RSSI、观测时间、原始载荷、序号和schema版本。平台默认不解码客户业务字段。','客户应用开发者','客户可以稳定解析并升级自己的应用','P0','公开样本与实际输出逐字段一致；同一schema兼容性测试通过；客户可以取得原始bytes及元数据，不被强制转换为厂商业务模型。',[12],'固件与接口研发','平台基础',notes='随机蓝牙地址不能被宣称为客户终端的稳定身份；终端业务身份解析由客户应用按其协议完成。')
add(14,'数据采集','配置经验证的扫描和过滤参数','功能','公开首销SKU支持的扫描窗口、周期、PHY及按地址、UUID、厂商字段等过滤能力，并给出默认模板和资源限制；不建设通用云解析器。','客户开发者','减少无关广播和接入调试工作','P0','在参考发送端验证每项售卖能力；修改过滤可回退，记录有效数据率与流量；不支持的过滤类型不能被提交为成功。',[12,13],'固件与测试','客户控制台')
add(15,'设备健康','显示网关连接和运行健康','功能','显示最后心跳、在线可疑离线、网络、运行时间、重启原因、固件和CPU存储等实际可提供指标。建议测试60秒心跳和连续三个周期缺失的离线基线，最终按型号批准。','客户与内部支持','及时判断购入网关是否正常运行','P0','受控断网和恢复后状态按批准窗口变化；可见最后心跳和判断依据；缺少端侧指标不显示伪造正常值。',[6,12],'固件与平台后端','客户控制台')
add(16,'通道健康','区分采集上行和客户接收状态','功能','分别显示扫描活跃、最近观测、端点连接、最近上传确认、失败码、队列水位和丢弃数。提供网关离线、通道失败、缓存满等固定健康告警及一种基础通知；客户应用业务告警由客户实现。','客户开发者与支持人员','避免网关在线但数据通道失效','P0','保持管理心跳并令客户端点拒绝数据，通道能独立告警；恢复后关闭相应健康事件。Broker PUBACK或HTTP2xx只标接收方接受，不标客户应用已处理成功。',[13,15,17,18],'固件与平台后端','客户控制台',notes='客户终端停止广播可能是正常行为；无约定采样周期时只显示最后观测，不擅自宣称终端故障。')
add(17,'数据可靠性','定义离线缓存和确认边界','技术','端侧数据持久队列按容量、时间和优先级工作，明确何时删除、满载策略和丢弃计数；直连端点恢复后限速补报。确认点按协议约定，不默认承诺客户应用持久化成功。','客户开发者与固件人员','断网可恢复并能解释数据损失边界','P0','基准负载下断网、重启、恢复及缓存溢出测试通过；实际缓存窗口和损失可查；恢复时补报不长期阻塞新数据。',[6,12,13,30],'固件与测试','平台基础',notes='MQTT按实际支持QoS约定Broker确认，HTTPS约定接收响应；应用级ACK仅在双方实现和验证后承诺。')
add(18,'数据可靠性','提供序号时间和重传语义','技术','使用稳定事件ID或boot_id加序号，区分观测时间与发送时间并标记时间质量和补报。说明重传去重与多网关重复观测的差异，由客户应用依约处理。','客户应用开发者','避免客户应用因重传乱序产生错误','P0','重复、乱序、时钟未同步和断网补报样本可由官方示例识别；相同载荷的新观测不被误删，跨网关观测保留来源。',[13,17],'固件与接口研发','平台基础')
add(19,'开发者接口','开放网关管理REST API','技术','提供设备列表、详情、能力、健康、配置、任务及固件状态等版本化管理API，行为与控制台一致；管理接口与客户业务数据接口分开。','客户系统开发者','客户可在自己的应用管理已购网关','P0','参考程序完成授权设备列表、健康查询和异步配置任务；分页、错误码和版本文档齐全，跨客户或越权设备请求拒绝。',[3,4,12,15,20,30],'平台后端与接口研发','平台基础')
add(20,'开发者接口','管理服务账号和API凭据','技术','生产应用使用独立服务账号，授权到项目、设备组和操作范围，支持凭据创建、到期、轮换、吊销及调用限额；不要求客户用个人密码对接。','客户管理员与开发者','使客户应用可长期安全运行','P0','服务账号只能访问授权设备和接口；吊销与权限缩减生效可测；轮换按批准窗口工作，密钥不在普通查询中回显。',[3,4,6,30],'平台后端与安全','客户控制台')
add(21,'开发者接口','区分命令接受执行和未知结果','技术','远程命令具有command_id、有效期、目标、幂等键和设备级状态；API受理返回任务标识，设备确认与实际执行结果分开，过期或未知结果不能被显示为成功。','客户系统开发者','客户应用可以正确处理异步设备操作','P0','重复幂等请求返回原任务；断网、过期、迟到回执和设备重启测试不重复执行危险动作；未确认执行显示未知并提供查询路径。',[12,15,19,20,30],'固件与平台后端','平台基础')
add(22,'远程配置','确认期望配置与实际配置一致','技术','配置版本包含期望、设备实际上报与最后同步时间；识别漂移，按型号校验参数，网络和端点变更具备设备端恢复策略。','客户管理员与开发者','远程配置可验证且失败可恢复','P0','离线下发不显示成功；设备实际生效才更新完成状态；错误网络配置按声明机制恢复，本地变更能被识别并解释。',[10,11,12,15,21],'固件与平台后端','客户控制台')
add(23,'联调工具','提供限时原始报文调试窗口','功能','客户显式授权后按网关开启有时限、条数和大小限制的调试会话，显示连接状态、原始包、元数据和接口响应，支持下载少量样本；正常运行不汇聚客户全部数据。','客户应用开发者','快速定位数据封装和接入问题','P0','会话到期自动停止采集，权限撤销立即阻断；同一网关采样限额生效；敏感字段可屏蔽，样本按批准的短留存窗口删除。',[4,12,13,15,18,20,30],'客户端与平台后端','客户控制台',notes='默认只回传管理与健康元数据。业务载荷回我方云仅限客户主动启用的调试会话，须明确用途与留存。')
add(24,'开发者资料','交付协议文档样例和快速开始','功能','为首销SKU提供OpenAPI、数据schema、MQTT主题或HTTP路径、鉴权、错误码、版本和资源限制；提供至少一个可运行收数及管理示例，不建设泛化应用开发平台。','客户应用开发者','降低客户接入成本并支撑网关成交','P0','未参与研发的工程师按文档完成网关激活、客户端点收数和管理API调用；示例与当前固件自动样本或人工契约检查一致。',[11,13,14,19,20,21],'接口研发与技术支持','客户控制台')
add(25,'安装交付','验证管理和数据两条链路','功能','安装验收分别检查我方管理连通、客户端点连通、参考发送端报文和客户示例程序收数；保存SN、版本、端点指纹及测试结果，密钥不入报告。','客户开发者与交付人员','避免以管理云在线代替客户接入成功','P0','完成一个参考端点的端到端验收；若客户不提供消费确认，只记传输确认或待客户确认，不能出具应用业务处理成功结论。',[8,10,11,15,16,24],'交付与测试','出厂与交付工具')
add(26,'内部售后','建立网关诊断与支持工作台','功能','内部按SN关联出厂、激活、客户、固件、健康、通道错误和操作记录，生成诊断编号；不建设客户业务工单或监测应用，必要时关联已有客服系统。','售后工程师','减少往返询问和现场维护','P0','预置端点鉴权失败、缓存积压和解析封装异常可从诊断编号追到证据；默认不可查看未授权客户原始BLE数据，访问可审计。',[5,7,8,15,16,23,30,33],'售后与平台后端','内部运营售后台')
add(27,'固件升级','执行签名与兼容预检','技术','固件包与manifest包含型号、硬件范围、版本依赖、哈希和签名；设备端校验真实性，云端校验目标和发布权限。','固件发布人员','防止错版或被篡改固件损坏网关','P0','错型号、修改包、错误签名和不满足版本依赖均被拒绝；下载完成不等于升级成功。',[5,12,30],'固件与平台后端','内部运营售后台')
add(28,'固件升级','提供人工小批试升与逐台结果','功能','首期人工选择小批、维护时间和暂停后续下发，显示每台下载、安装、启动、实际版本、管理与客户通道恢复结果，再经确认扩大范围。','固件发布与售后人员','在出货增长前控制升级风险','P0','试升设备确认版本与健康才记成功；失败、未执行和未知单列；暂停后不再向尚未执行目标下发，客户通道异常可阻止扩大范围。',[15,16,21,27],'固件与平台后端','内部运营售后台')
add(29,'固件升级','验证升级失败恢复机制','技术','首销网关优先支持A/B或已验证等效恢复；受限型号明确现场恢复方案。任务中止仅停止扩散，不自动等同回滚；升级恢复后客户端点及配置保持或按规则恢复。','固件与售后人员','避免升级导致网关大面积失去服务','P0','在下载、写入和首次启动中断电源，型号按声明路径回到可管理状态；受限型号现场恢复步骤演练通过，客户通道配置无意外泄漏。',[10,12,22,27,28],'固件与测试','平台基础')
add(30,'平台安全','验证客户隔离和关键审计','技术','API、消息、缓存、任务和调试会话统一按可信客户身份授权；管理及数据链路使用受支持TLS，秘密受控存储；审计认领、调试、导出、配置、升级和支持访问。','客户管理员与安全人员','防止串户和不可追责操作','P0','跨客户管理、任务与调试访问均拒绝；关键审计含主体、SN、动作、时间和结果；数据端点秘密和私钥不在普通日志、导出或诊断报告出现。',[3,4,5,6],'安全与平台后端','平台基础')
add(31,'平台运营','核定容量边界与监控服务链路','非功能','区分网关射频采集能力、客户端点直连吞吐和我方控制面负载；按预计出货、心跳、任务、调试量、报文大小和网络条件测量，不以云压测代替空口接收率。','设备研发与平台运维','让销售容量承诺与服务成本可验证','P0','按批准设备与资源完成正常、突发、断网及恢复测试，报告采集、上行、队列与管理API指标；管理故障和客户端点故障分开告警。',[12,14,15,16,17,18,21,28],'测试与运维','平台基础')
add(32,'平台运营','限定云端数据并验证备份恢复','非功能','我方云保存设备、客户、配置、任务、授权和审计等必要管理数据，调试载荷短期按需保留；不提供客户传感器长期历史服务。备份身份及控制状态，保护密钥并演练恢复。','平台运营与安全人员','控制硬件附送云服务成本与恢复风险','P0','列出持久化和禁止默认回传的数据清单；调试样本按政策清除。完成恢复演练，建议RPO十五分钟、RTO四小时需批准，恢复后归属、吊销与任务语义一致。',[2,6,8,21,22,23,27,30],'运维与数据研发','平台基础')
add(33,'服务政策','显示服务状态并提供到期交接','功能','分别显示激活、保修、管理云和维护期及支持范围；到期按已批准政策提示、保留必要导出与交接路径，不隐式改变网关本地能力或客户端点数据通道。','客户管理员与售后','让硬件与平台服务边界清楚','P0','保修到期但管理云有效、管理云到期但保修有效的样本状态独立；按批准规则演示提示与管理配置导出，客户数据通道行为与合同一致。',[2,8,9,30,32],'产品与平台后端','客户控制台')

add(34,'规模管理','支持分组批量配置','功能','按客户项目、型号、固件、批次和设备组筛选，预览差异并分批执行兼容参数，保留每台实际结果与失败重试关联。','客户管理员与售后','减少大批网关重复配置工作','P1','混合型号目标自动排除不兼容参数；成功、失败、未执行和未知数量与设备明细一致，重试不创建失联任务。',[12,21,22],'前端与平台后端','客户控制台')
add(35,'固件升级','自动灰度与停止扩散','功能','在人工试升验证基础上增加批次、最小样本、观察窗口、失败阈值和维护时间，健康回归触发自动停止，保留判断样本。','固件发布人员','使网关规模增长后升级可控','P1','注入批准比例的失败或客户通道回归后自动停止后续批次；停止不被标为自动回滚，已执行设备结果不丢失。',[16,28,29,31],'固件与平台后端','内部运营售后台')
add(36,'固件升级','管理测试试点和正式版本','功能','区分测试、试点与正式渠道，按硬件批次维护升级路径、发布说明、已知问题和支持截止信息，客户可核对当前版本支持范围。','产品与固件发布人员','减少错版和售后知识分散','P1','测试版本不默认推向正式客户；SN可追到升级路径和发布说明，错误跨版本升级被阻断。',[7,12,27,28,33],'产品与固件','内部运营售后台')
add(37,'出厂交付','追踪出货激活和联调完成','功能','按出货批次或已有订单号统计已发货、未激活、管理上线和客户联调完成状态，销售或交付跟进未使用设备；不建设完整订单系统。','销售与交付负责人','提高已售网关有效使用率','P1','批次统计可回到SN；管理上线与客户示例收数完成分别统计，未激活不算有效使用。',[7,8,25,33],'销售运营与数据研发','内部运营售后台')
add(38,'出厂交付','对接已有产测和出货工具','技术','规模增长后提供轻量接口接收SN、批次、产测和出货记录，逐项报错且幂等；密钥注入使用受控制造流程，不在普通业务记录传输私钥。','工厂与设备运营','降低人工出货数据错误','P1','同一产测和出货记录重复推送不重复建档；失败重放后状态一致，生产接口权限与客户管理接口隔离。',[6,7,30,37],'工厂工具与平台后端','出厂与交付工具')
add(39,'硬件售后','关联保修返修和替换SN','功能','维护RMA编号、故障分类、原SN、替换SN、保修判定和结论，可关联已有客服或ERP；只围绕自有网关售后，不建设通用工单产品。','售后与质量人员','控制网关维修成本并保留问题证据','P1','完成一次返修与一次换货记录，旧新SN关系可追溯；换货不复制设备密钥，归属和客户端点凭据按授权重新配置。',[9,26,33,37],'售后与质量','内部运营售后台')
add(40,'支持授权','提供限时按设备支持授权','功能','客户按设备、动作、元数据与调试载荷范围授予内部支持，设截止时间并可撤销；查看管理健康不自动获得客户BLE载荷查看权。','客户管理员与售后','规模售后仍保持客户控制权','P1','支持人员只能操作被授权设备和范围；到期及撤销生效可测，调试载荷授权单独记录且支持行为可审计。',[4,5,23,26,30],'安全与平台后端','内部运营售后台')
add(41,'质量分析','按批次和固件聚合故障','功能','汇总网关离线、重启、通道失败、缓存溢出、升级和RMA，按型号、硬件批次和固件版本观察，保留样本量及原设备清单。','质量与产品人员','及时发现影响硬件口碑的共性问题','P1','混合批次样本统计能回到SN和事件；无足够样本不直接宣称故障率变化具有确定因果。',[7,15,16,28,36,39],'质量与数据研发','内部运营售后台')
add(42,'规模管理','提供批量检索导入和导出','功能','按SN、客户、项目、型号、固件、批次、健康及服务状态检索网关，支持权限校验的批量导入与管理台账导出，不导出客户端点秘密。','客户管理员与设备运营','支撑批量交付和故障处理','P1','组合筛选与导出数量一致，重复非法和越权记录逐行报错，导出不包含密钥及未授权客户记录。',[7,8,12,15,16,30,33],'前端与平台后端','客户控制台')
add(43,'内部成本','统计管理云和支持成本','业务','按硬件SKU、客户和批次统计管理连接、任务、调试字节、通知和支持工时；客户数据直连只记录必要汇总量，不收集全部内容，不自动生成客户订阅账单。','经营与平台运营人员','让硬件毛利覆盖随附服务成本','P1','固定样本的管理用量可对账，调试与常态业务流量分开；成本参数有版本，客户侧没有未约定收费。',[2,16,26,31,32,39],'经营与平台运营','内部运营售后台')
add(44,'产品运营','衡量客户接入和远程解决效果','业务','统计出货激活率、首次联调耗时、有效上行设备率、远程解决率、升级恢复及单台管理云成本，先建立可解释基线再批准改善目标。','产品与经营负责人','按网关经营结果决定功能投入','P1','指标有时间窗、分母、排除项和责任人，可追到SN、联调报告和支持记录；客户应用业务成功率不由平台擅自推算。',[25,28,37,39,43],'产品运营与数据研发','内部运营售后台')
add(45,'通道健康','增强健康通知责任和维护窗口','功能','为网关及通道固定健康事件设置项目责任人、确认时限、维护窗口和升级提醒，扩充通知渠道时核对外部成本；不增加传感器业务规则。','客户运维负责人','减少健康通知噪声和无人响应','P1','维护窗口抑制有记录，确认后不再按未确认规则重复提醒；责任人变更不改写历史处理者。',[4,16,33],'产品与平台后端','客户控制台')
add(46,'开发者资料','提供维护中的管理客户端库','技术','根据真实客户语言需求维护至少一套管理API客户端库，覆盖鉴权、分页、异步任务查询和错误处理；数据解析示例保持标准原始信封边界。','客户系统开发者','减少客户重复编写基础接入代码','P1','客户端库对当前API契约测试通过，版本、许可证和示例可查；密钥不写入代码仓库，客户可按文档直接HTTP调用替代库。',[19,20,21,24],'接口研发','平台基础')
add(47,'开发者服务','发布接口状态和兼容变更通知','功能','向受影响客户提供管理API状态、版本弃用窗口、固件协议变更和故障通报入口，区分我方故障与客户端点不可达。','客户开发者与IT','降低接口变更造成的客户停用','P1','一次模拟API变更可定位受影响版本与客户，发出可查通知；客户端点故障不被标为我方全局云故障。',[19,24,31,33,36],'平台运维与技术支持','客户控制台')
add(48,'开发者服务','提供可重复的协议联调测试','技术','提供受控BLE样例、MQTT或HTTPS接收示例和管理接口契约测试，覆盖断网、重复、时钟异常与不兼容报文；不替客户开发业务逻辑。','客户开发者与测试人员','缩短双方定位责任和联调周期','P1','独立工程师使用测试材料重现常见错误；样例覆盖已售协议版本，测试结果能回到原始输入与预期输出。',[13,17,18,19,24,25],'接口研发与测试','平台基础')
add(49,'联调工具','生成受控故障快照和诊断包','功能','客户授权后在特定错误触发时保存少量管理日志、队列指标和必要载荷样本，设容量及留存；售后导出诊断包不包含端点秘密。','客户开发者与售后','捕获难以复现的网关问题','P1','触发一次端点失败和一次队列溢出生成受限快照；超额停止、到期删除、撤销访问和敏感字段屏蔽均可验证。',[16,23,26,30,32,40],'固件与平台后端','内部运营售后台')
add(50,'数据通道','按需优化批处理和压缩','技术','针对经测量的网关上行瓶颈提供经版本化的批处理、压缩或边缘去重配置；保留原始观测语义，客户接收端必须明确支持。','客户开发者与固件人员','减少带宽和热点负载','P1','参考负载下报告带宽、时效和数据完整性变化；客户不支持格式时拒绝开通或可回退；相同载荷的新观测不被误删。',[12,13,14,17,18,24,31],'固件与测试','平台基础',condition='出现已测带宽或上行负载瓶颈，且客户端支持新格式')
add(51,'数据通道','按型号增加受控端点故障切换','技术','在单端点稳定后，按型号及客户要求提供主备端点或连接恢复策略，明确切换顺序、回切、重复与队列语义，不默认同时多发。','客户开发者与IT','提高特定交付环境的数据上行韧性','P1','主端点不可达后按策略切换并可恢复，输出可关联序号；客户能处理重复，凭据与数据不被发送到未授权端点。',[11,17,18,22,24,30],'固件与测试','平台基础',condition='型号支持且客户明确配置主备服务')

add(52,'连接型SKU','提供GATT连接读写与通知能力','技术','仅当连接型网关被对外销售并承诺GATT时，开放连接断开、服务与特征发现、read、write和notify及会话限额；不可幂等操作超时不得盲目重试。','客户设备应用开发者','兑现连接型网关的核心售卖能力','P0','按该SKU承诺验证并发、读写、通知和断线；命令接受与设备实际结果分开；未获应用确认的动作显示结果未知；纯采集SKU明确拒绝连接操作。',[12,13,19,20,21,24,30],'固件与接口研发','平台基础',condition='仅连接型SKU的售卖承诺包含GATT时，作为该SKU首发验收；纯采集SKU不启用',notes='读取及notify值按批准的数据通道交客户；经我方云返回业务载荷须明确授权、最小留存及日志屏蔽。')
add(53,'连接型SKU','治理配对密钥与连接调度','技术','连接型SKU按已支持终端安全流程实现配对、密钥保护、租约及并发调度，避免多网关或多个客户程序争用同一终端；客户私有协议和授权材料由对接契约明确。','客户设备研发与安全人员','连接能力安全可用且不破坏采集','P0','批准终端完成配对、断线重连和并发争用测试；过期租约不能继续操作，秘密不明文导出；连接负载下采集性能达到该SKU批准基线。',[6,12,14,21,30,52],'固件与安全','平台基础',condition='仅对销售的连接型SKU及已批准终端安全流程启用；随该SKU首发验收')
add(54,'终端维护','按订单支持特定终端OTA','技术','只有终端及网关具备经验证升级协议、签名和恢复机制，且订单需要时开放终端OTA；与网关升级分开管理包、对象、会话和耗电。','客户设备研发与售后','满足特定客户的终端维护需求','P2','批准终端完成正常、低电量拒绝、中断和恢复测试；网关包不能发给终端，不支持型号明确拒绝。',[12,21,27,28,29,52,53],'固件与测试','平台基础',condition='客户提供或确认终端升级协议，型号能力具备且订单要求；非默认网关功能')
add(55,'可选数据模式','按订单提供云端转发通道','技术','客户确需我方托管数据出口时提供有界云转发，约定认证、目的端点、吞吐、队列、留存、重试和费用归属；不自动变为客户业务数据平台。','客户IT与解决方案人员','支持无法直连或要求集中转发的订单','P2','在冻结负载下演示转发、失败重试、限额和删除；明确每个确认点及责任边界，客户不启用时数据仍走直连模式。',[2,11,13,17,18,30,31,32,43],'平台后端与解决方案','平台基础',condition='真实订单需要我方数据托管，并批准持续成本与数据政策')
add(56,'部署模式','按订单提供独立或离线管理部署','业务','对隔离网络或私有化订单提供同一管理内核的独立实例，冻结激活、证书、升级包、日志、备份和支持责任，不首期并行维护多套产品。','客户IT与采购人员','满足明确的网关采购部署条件','P2','目标环境完成安装、设备管理、升级、备份和恢复演练；无外网激活和授权路径可执行，功能差异明确。',[2,6,19,24,27,29,30,31,32,33],'解决方案与运维','平台基础',condition='有明确隔离或私有化订单及独立交付预算')
add(57,'企业身份','按订单对接企业单点登录','技术','客户确需统一身份时对接一种约定OIDC或SAML身份源，映射平台已有角色并保留受控应急管理入口。','客户IT管理员','使网关管理融入企业账号治理','P2','测试身份源完成登录、角色映射、离职禁用和证书轮换；错误映射不扩大设备权限，应急登录有审计。',[3,4,5,30],'平台后端与安全','客户控制台',condition='客户采购要求企业身份集成')
add(58,'开发者接口','推送网关管理健康事件','技术','按集成订单提供管理及通道健康事件Webhook或MQTT出口，定义event_id、鉴权、时间、至少一次投递、重试与死信；不承载客户传感器业务规则。','客户系统开发者','客户可在自有运维系统接收网关事件','P2','重复、失败、超时和密钥轮换测试通过；接收方按event_id幂等，授权重放可查，不泄漏其他客户设备事件。',[16,18,19,20,21,24,30],'接口研发与平台后端','平台基础',condition='客户需要事件推送而非管理API轮询')
add(59,'本地管理','按型号提供脱云管理API','技术','对脱云订单和支持型号提供本地受鉴权的管理接口或工具，涵盖能力、网络、配置、诊断与签名升级；客户归属、日志与远程管理冲突规则明确。','客户现场系统开发者','让网关在受限网络下可维护','P2','无互联网环境完成本地配置、数据直连和升级恢复验证；未授权本地请求拒绝，恢复联网后配置冲突按批准规则处理。',[6,9,10,11,12,21,22,24,27,29,30],'固件与接口研发','平台基础',condition='自有型号具备本地管理能力且客户要求脱云交付')
add(60,'出厂定制','按订单预配置客户数据通道','功能','大批采购可在工厂预置客户端点和设备模板，密钥按受控流程生成或注入，按批次校验并允许客户验收后轮换；不把客户秘密写入普通出货文件。','工厂与客户IT','减少大批网关现场逐台配置','P2','订单批次预配置与客户端点收数验收一致；错客户模板被阻断，出货导出无秘密，首次交付可完成凭据轮换。',[6,7,8,11,12,22,24,25,30,38],'工厂工具与固件','出厂与交付工具',condition='批量硬件订单要求工厂预配置并具备安全注入条件')

policy=[
 {'id':'SP-01','decision':'硬件随附管理云服务期限','to_confirm':'按SKU包含多久管理云和软件支持，出货、激活或验收何时起算，长期未激活如何处理。','principle':'硬件收费不自动代表永久免费云；先写清服务边界，再执行到期策略。'},
 {'id':'SP-02','decision':'管理服务到期与客户数据直连','to_confirm':'到期后管理、诊断、固件、安全修复和管理配置导出的保留范围，宽限时间与通知方式。','principle':'硬件所有权、保修和管理服务分离；不隐式阻断本地功能或客户端点数据直连。'},
 {'id':'SP-03','decision':'控制面与数据面责任','to_confirm':'默认客户直连协议、客户Broker或HTTP确认边界、缓存窗口、客户消费责任及我方支持范围。','principle':'管理云在线、端点接受数据与客户应用处理完成分别确认，不互相代替。'},
 {'id':'SP-04','decision':'调试载荷与云转发成本','to_confirm':'主动调试采样上限、短留存、权限和删除；云转发是否只按订单开通及如何承担持续成本。','principle':'常态只传必要管理元数据；不建设传感器长期历史服务，不默认双发。'},
 {'id':'SP-05','decision':'网关和BLE终端适配责任','to_confirm':'哪些SKU承诺扫描、GATT及终端OTA；客户终端私有协议、安全与业务应用由谁实现。','principle':'只管理自有网关，同时允许透传客户第三方BLE终端数据；这不等于接入第三方网关生态。'},
 {'id':'SP-06','decision':'换货转移与凭据交接','to_confirm':'旧新SN、保修与管理服务继承，客户端点秘密清除、重新注入或轮换，以及停用旧网关的责任。','principle':'不复制设备身份密钥，不把旧客户数据和秘密交给新客户。'},
 {'id':'SP-07','decision':'固件与接口版本支持期','to_confirm':'管理API、数据schema、旧固件和客户端示例的兼容期限及停止维护通知。','principle':'不承诺所有旧硬件无限升级；破坏性变更需给客户明确迁移窗口。'}
]
metrics=[
 {'id':'M-01','name':'出货激活率','formula':'达到观察期的出货批次中已激活SN数 / 同批已交付SN数','owner':'销售运营','decision_use':'发现已售但未上线的网关，退货及试产单列。'},
 {'id':'M-02','name':'首次客户联调耗时','formula':'从首次配网到客户参考程序收到有效标准报文的耗时，统计中位数和P95','owner':'技术支持','decision_use':'检验配网、协议说明和示例是否减少接入成本。'},
 {'id':'M-03','name':'有效上行网关率','formula':'在约定上报窗口内具备有效采集且端点确认成功的应工作网关数 / 应工作网关数','owner':'产品运营','decision_use':'只表达约定确认点；客户应用业务成功率由客户测量。'},
 {'id':'M-04','name':'远程解决率','formula':'无需现场出勤恢复并确认的有效网关故障数 / 有效网关故障数','owner':'售后','decision_use':'衡量诊断、配置、文档和升级对售后成本的作用。'},
 {'id':'M-05','name':'升级健康成功率','formula':'实际目标版本且管理与客户通道健康通过的执行数 / 已开始升级执行数','owner':'固件与质量','decision_use':'未执行、取消、回滚和未知分别列出，不能用下载完成代替成功。'},
 {'id':'M-06','name':'单台管理服务成本','formula':'同期可归属管理云、通知、调试及支持成本 / 同期活跃网关数','owner':'经营','decision_use':'与SKU毛利、随附期限核对，内部计量不自动变成客户收费。'},
 {'id':'M-07','name':'批次报修率','formula':'固定观察期内有效报修SN数 / 同批已交付且达到观察期SN数','owner':'质量','decision_use':'按硬件批次和固件版本列样本量及故障原因，不把相关性直接作因果。'},
 {'id':'M-08','name':'客户接口接入成功率','formula':'通过既定参考联调用例的客户项目数 / 进入联调的客户项目数','owner':'解决方案','decision_use':'用标准输出与管理API可用性评估开发者体验，不包含客户业务应用开发结果。'}
]
by={x['id']:x for x in items}
assert len(by)==len(items)==60
assert all(d in by for x in items for d in x['dependencies'])
mark={}
def visit(k):
 assert mark.get(k)!=1, f'cycle {k}'
 if mark.get(k)==2:return
 mark[k]=1
 for dep in by[k]['dependencies']:visit(dep)
 mark[k]=2
for k in by:visit(k)
rank={'首期':0,'规模化':1,'订单驱动':2}
assert all(rank[by[d]['phase']]<=rank[x['phase']] for x in items for d in x['dependencies'])
assert all(not any(w in x['title'] for w in ['定位','轨迹','地图','盘点']) for x in items)
doc={
 'title':'自有网关与客户应用开发平台功能规划需求清单',
 'version':'1.1',
 'checked_date':'2026-11-07',
 'business_model':'硬件收费，平台管理自有网关并服务客户开发应用；我方控制面与客户数据面分离。',
 'assumptions':['用户明确不考虑定位，且以网关为主，由客户开发应用。','只管理自有网关；客户可通过网关采集第三方BLE终端，原始透传与客户侧解码不意味着接入第三方网关生态。','默认模式为我方管理云加客户MQTT或HTTPS数据端点直连；首期至少验证一种与首销SKU匹配的数据协议。','平台分客户及开发者控制台、内部设备运营售后台、轻量出厂与交付工具，复用已有ERP、客服和产测系统。','我方默认保存必要管理元数据，客户BLE载荷仅在主动限时调试或明确云转发订单中回传。','P0包括33条通用首期要求与2条连接型SKU条件首期要求；未销售连接型SKU时后两条不进入通用首期验收。','P1为规模交付提效，P2为具体订单或能力条件触发，不据此首期开发所有功能。','心跳、缓存、吞吐、调试留存、RPO/RTO及服务期限均需设备测试和成本评审批准；未承诺永久免费云服务。'],
 'requirements':items,
 'excluded_features':['所有定位、地图、轨迹、电子围栏、资产盘点及相关位置算法。','温湿度等客户业务看板、传感器业务规则、长期业务历史和客户行业工单应用。','第三方网关接入、通用设备生态、应用市场与通用低代码规则编排。','独立SaaS套餐商城、自助订阅、自动续费、账单和在线支付。','完整MES、ERP、CRM系统；仅保留设备全生命周期记录及与已有工具的轻量接口。','未获明确订单支持的私有化分支、多云和大型渠道授权体系。'],
 'service_policy_decisions':policy,
 'metrics':metrics,
 'validation':{'requirement_count':len(items),'unique_ids':True,'dependency_references_valid':True,'dependency_graph_acyclic':True,'all_dependencies_within_phase':True,'first_phase_dependencies_within_first_phase':True,'no_positioning_requirements':True,'generic_first_phase_count':33,'conditional_first_phase_count':2,'priority_counts':dict(Counter(x['priority'] for x in items)),'phase_counts':dict(Counter(x['phase'] for x in items)),'surface_counts':dict(Counter(x['surface'] for x in items))}
}
